#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

const int MOD = 1000003;

ll power(ll base, ll exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1)
            result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, c;
    cin >> n >> c;

    vector<ll> fact(MOD), invFact(MOD);
    fact[0] = 1;

    for (int i = 1; i < MOD; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[MOD - 1] = power(fact[MOD - 1], MOD - 2);
    for (int i = MOD - 1; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    auto smallBinomial = [&](int a, int b) -> ll {
        if (b < 0 || b > a)
            return 0;
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
    };

    ll total = 1;
    ll a = n + c;
    ll b = c;

    while (a > 0 || b > 0) {
        int ai = a % MOD;
        int bi = b % MOD;

        if (bi > ai) {
            total = 0;
            break;
        }

        total = total * smallBinomial(ai, bi) % MOD;
        a /= MOD;
        b /= MOD;
    }

    cout << (total - 1 + MOD) % MOD << '\n';
    return 0;
}

