    while (exponent > 0) {
        if (exponent & 1)
            result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, c;
    cin >> n >> c;

    vector<int> factorial(MOD), inverseFactorial(MOD);
    factorial[0] = 1;

    for (int i = 1; i < MOD; ++i)
        factorial[i] = static_cast<ll>(factorial[i - 1]) * i % MOD;

    inverseFactorial[MOD - 1] = power(factorial[MOD - 1], MOD - 2);

    for (int i = MOD - 1; i > 0; --i)
        inverseFactorial[i - 1] =
            static_cast<ll>(inverseFactorial[i]) * i % MOD;

    auto smallBinomial = [&](int a, int b) -> ll {
        if (b < 0 || b > a)
            return 0;
        return static_cast<ll>(factorial[a]) *
               inverseFactorial[b] % MOD *
               inverseFactorial[a - b] % MOD;
    };

    auto lucasBinomial = [&](ll a, ll b) -> ll {
        ll result = 1;
        while (a > 0 || b > 0) {
            int ai = a % MOD;
            int bi = b % MOD;

            if (bi > ai)
                return 0;

            result = result * smallBinomial(ai, bi) % MOD;
            a /= MOD;
            b /= MOD;
        }
        return result;
    };

    ll result = (lucasBinomial(n + c, c) - 1 + MOD) % MOD;
    cout << result << '\n';

    return 0;
}

